    26|// Instagram-style cache-first QueryClient:
    27|// - Long staleTime so cached data renders instantly (no spinner)
    28|// - Long gcTime so cache survives navigation between tabs
    29|// - refetchOnMount: false to avoid refetch on tab switches (served from cache immediately)
    30|// - placeholderData: keepPreviousData so paginated feeds never flash blank
    31|// - retry: 1 with short delays for fast recovery
    32|const queryClient = new QueryClient({
    33|  defaultOptions: {
    34|    queries: {
    35|      staleTime: 5 * 60_000, // 5 minutes — data stays fresh, no refetch on mount
    36|      gcTime: 30 * 60_000, // 30 minutes — cache survives tab navigation
    37|      retry: 1,
    38|      refetchOnMount: false, // Don't refetch when switching tabs — serve cache instantly
    39|      refetchOnReconnect: true,
    40|      refetchOnWindowFocus: false,
    41|      networkMode: 'online',
    42|      // keepPreviousData: true — serve stale data while refetching (Instagram pattern)
    43|    },
    44|    mutations: {
    45|      retry: 1,
    46|      networkMode: 'online'}}});
