     4|/**
     5| * Samsung Internet / Android Chrome keyboard detection via the VisualViewport API.
     6| *
     7| * On Samsung Browser, `window.innerHeight` shrinks when the soft keyboard opens,
     8| * but the resize event may fire inconsistently. The VisualViewport API is the
     9| * reliable signal: when `visualViewport.height` drops below `window.innerHeight`,
    10| * the keyboard is visible. The difference is the keyboard height.
    11| *
    12| * Returns:
    13| * - keyboardHeight: px of the soft keyboard (0 when closed)
    14| * - isKeyboardVisible: whether the keyboard is open
    15| * - viewportHeight: current visualViewport.height
    16| */
    17|export function useWebKeyboard() {
    18|  const [keyboardHeight, setKeyboardHeight] = useState<number>(0);
    19|  const [isKeyboardVisible, setIsKeyboardVisible] = useState<boolean>(false);
    20|  const [viewportHeight, setViewportHeight] = useState<number>(0);
    21|  const prevHeightRef = useRef<number>(0);
    22|
    23|  useEffect(() => {
    24|    if (Platform.OS !== 'web') {
    25|      return;
    26|    }
    27|
    28|    const vv = window.visualViewport;
    29|    if (!vv) {
    30|      return;
    31|    }
    32|
    33|    const computeKeyboard = () => {
    34|      const vh = vv.height;
    35|      const wh = window.innerHeight;
    36|      setViewportHeight(vh);
    37|
    38|      // keyboard height = how much the visual viewport shrank relative to the window
    39|      const kbHeight = Math.max(wh - vh - vv.offsetTop, 0);
    40|      const visible = kbHeight > 80; // threshold to avoid false positives from URL bar
    41|
    42|      if (visible !== prevHeightRef.current > 0 || Math.abs(kbHeight - prevHeightRef.current) > 10) {
    43|        setKeyboardHeight(kbHeight);
    44|        setIsKeyboardVisible(visible);
    45|        prevHeightRef.current = kbHeight;
    46|      }
    47|    };
    48|
    49|    computeKeyboard();
    50|    vv.addEventListener('resize', computeKeyboard);
    51|    vv.addEventListener('scroll', computeKeyboard);
    52|
    53|    return () => {
    54|      vv.removeEventListener('resize', computeKeyboard);
    55|      vv.removeEventListener('scroll', computeKeyboard);
    56|    };
    57|  }, []);
    58|
    59|  return { keyboardHeight, isKeyboardVisible, viewportHeight };
