   147|/**
   148| * Scrolls an element into view above the keyboard on Samsung.
   149| * Uses visualViewport to calculate the correct offset.
   150| */
   151|export function scrollInputIntoView(element: HTMLElement | null) {
   152|  if (Platform.OS !== 'web' || !element) {
   153|    return;
   154|  }
   155|
   156|  const vv = window.visualViewport;
   157|  if (!vv) {
   158|    element.scrollIntoView({ block: 'center', behavior: 'smooth' });
   159|    return;
   160|  }
   161|
   162|  // Use rAF to wait for keyboard animation to settle
   163|  requestAnimationFrame(() => {
   164|    const rect = element.getBoundingClientRect();
   165|    const vvBottom = vv.height + vv.offsetTop;
   166|
   167|    // If the input is below the visible viewport (hidden by keyboard)
   168|    if (rect.bottom > vvBottom) {
   169|      const scrollAmount = rect.bottom - vvBottom + 20;
   170|      window.scrollBy({ top: scrollAmount, behavior: 'smooth' });
   171|    }
   172|  });
