     1|/**
     2| * Startup trace utility for IVX Holdings.
     3| *
     4| * Generates a unique trace ID per app launch and records checkpoints with
     5| * elapsed milliseconds so we can identify exactly where startup stops.
     6| *
     7| * The required startup trace must reach APP_INTERACTIVE for a successful launch.
     8| */
     9|
    10|const START_TIME_MS = Date.now();
    11|const TRACE_ID = `${START_TIME_MS.toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    12|
    13|export type StartupCheckpoint =
    14|  | 'APP_NATIVE_STARTED'
    15|  | 'JS_BUNDLE_STARTED'
    16|  | 'ROOT_COMPONENT_MOUNTED'
    17|  | 'APP_MOUNTED'
    18|  | 'ROOT_LAYOUT_RENDERED'
    19|  | 'ERROR_BOUNDARY_MOUNTED'
    20|  | 'PROVIDERS_STARTED'
    21|  | 'PROVIDERS_COMPLETED'
    22|  | 'PROVIDERS_MOUNTED'
    23|  | 'SPLASH_HIDE_STARTED'
    24|  | 'SPLASH_HIDE_COMPLETED'
    25|  | 'AUTH_INITIALIZATION_STARTED'
    26|  | 'AUTH_INITIALIZATION_COMPLETED'
    27|  | 'AUTH_INITIALIZATION_FAILED'
    28|  | 'AUTH_INIT_STARTED'
    29|  | 'AUTH_INIT_COMPLETED'
    30|  | 'AUTH_INIT_FAILED'
    31|  | 'ROUTER_READY'
    32|  | 'INITIAL_ROUTE_SELECTED'
    33|  | 'INITIAL_ROUTE_RENDERED'
    34|  | 'APP_INTERACTIVE';
    35|
    36|const recorded = new Set<StartupCheckpoint>();
    37|
    38|function elapsedMs(): number {
    39|  return Date.now() - START_TIME_MS;
    40|}
    41|
    42|function prefix(): string {
    43|  return `[IVX-STARTUP ${TRACE_ID} +${elapsedMs()}ms]`;
    44|}
    45|
    46|/** Record a startup checkpoint. Duplicate checkpoints are ignored. */
    47|export function logStartup(checkpoint: StartupCheckpoint, detail?: string): void {
    48|  if (recorded.has(checkpoint)) {
    49|    return;
    50|  }
    51|  recorded.add(checkpoint);
    52|  const msg = detail ? `${checkpoint} | ${detail}` : checkpoint;
    53|  console.log(prefix(), msg);
    54|}
    55|
    56|/** Record a startup error checkpoint with sanitized detail. */
    57|export function logStartupError(checkpoint: StartupCheckpoint, error: unknown): void {
    58|  const detail = error instanceof Error ? error.message : String(error ?? 'unknown');
    59|  // Redact any token-looking strings before logging.
    60|  const sanitized = detail
    61|    .replace(/eyJ[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*/g, '[REDACTED_JWT]')
    62|    .replace(/[0-9a-f]{32,}/g, '[REDACTED_HEX]')
    63|    .slice(0, 200);
    64|  console.warn(prefix(), `${checkpoint} | ${sanitized}`);
    65|}
    66|
    67|/** Get the current trace ID and elapsed time for diagnostics. */
    68|export function getStartupTraceInfo(): { traceId: string; elapsedMs: number; checkpoints: StartupCheckpoint[] } {
    69|  return { traceId: TRACE_ID, elapsedMs: elapsedMs(), checkpoints: Array.from(recorded) };
    70|}
    71|
    72|/** True if all required checkpoints have been recorded. */
    73|export function isStartupComplete(): boolean {
    74|  return recorded.has('APP_INTERACTIVE');
    75|}
    76|
    77|/** Get the trace ID for inclusion in error reports. */
    78|export function getStartupTraceId(): string {
    79|  return TRACE_ID;
